// French translation of the v2 room prose (beats, choice text/hint/outcome,
// field notes, explanations) for Act III. Registered under version 'v2'.
// Translated from the English v2 source directly, per CLAUDE.md's
// context-first rule. State-reactive (dynamic) beats live in fr-dynamic.ts:
// teleporter stage0 beat 3, butterfly-dream stage0 beat 2, the-cave stage0
// beats 2/3/4.
import { registerAll } from '../../engine/text/resolver';
import {
  roomBeatKey,
  roomChoiceHintKey,
  roomChoiceOutcomeKey,
  roomChoiceTextKey,
  roomExplanationKey,
  roomNoteBodyKey,
  roomNoteThinkersKey,
  roomNoteTitleKey,
} from '../../engine/text/keys';

// ---------- Act III: The Teleporter ----------
registerAll('v2', 'fr', {
  [roomBeatKey('teleporter', 0, 0)]: 'Une pièce avec un miroir noir en guise de sol et pas de mur du fond — juste un gouffre, et au-delà du gouffre, le chemin à suivre, inaccessible par aucun pont car il n\'y a pas de pont.',
  [roomBeatKey('teleporter', 0, 1)]: 'Il y a, à la place, une cabine. Acier brossé, doucement éclairée, des portes comme une guillotine polie. Les instructions sont imprimées dans une police choisie pour être apaisante.',
  [roomBeatKey('teleporter', 0, 2)]: 'ENTREZ. VOUS SEREZ SCANNÉ JUSQU\'À L\'ATOME, DÉSASSEMBLÉ, ET IMPRIMÉ — PARFAITEMENT — DE L\'AUTRE CÔTÉ. LA COPIE SE SOUVIENDRA D\'AVOIR LU CE PANNEAU. LA COPIE AURA L\'IMPRESSION D\'AVOIR TRAVERSÉ. LA COPIE EN SERA TRÈS SÛRE.',
  [roomBeatKey('teleporter', 0, 4)]: 'Le Placeur : Je la prends quotidiennement. Ou quelqu\'un le fait — celui qui arrive a mes souvenirs et mes griefs et dépose mes rapports, alors ici plus personne ne demande. Le gouffre se moque de la métaphysique. Le gouffre se soucie seulement qu\'il n\'y ait pas de pont.',
  [roomChoiceTextKey('teleporter', 'step-through')]: 'Entrez. Quoi qu\'il arrive sera sûr d\'être vous, et la certitude est tout ce que vous avez jamais eu.',
  [roomChoiceHintKey('teleporter', 'step-through')]: 'Faites confiance au motif.',
  [roomChoiceOutcomeKey('teleporter', 'step-through', 0)]: 'Les portes se ferment. Il n\'y a pas de douleur, pas de lumière, pas de tunnel — il n\'y a que le panneau de l\'autre côté, qui dit : MERCI. Et vous vous souvenez avoir lu le premier panneau, et vous vous souvenez avoir décidé, et vous vous sentez exactement comme quelqu\'un qui a traversé.',
  [roomChoiceOutcomeKey('teleporter', 'step-through', 1)]: 'Ce qui est, bien sûr, exactement ce que le panneau disait que la copie ressentirait. Vous vérifiez vos mains. Elles sont très convaincantes. Vous êtes soit la même personne, soit la meilleure preuve que « la même personne » n\'a jamais été qu\'un sentiment portant les habits d\'un fait.',
  [roomChoiceOutcomeKey('teleporter', 'step-through', 2)]: 'Le Placeur : (déjà de l\'autre côté — ou un Placeur l\'est) Indolore, voyez-vous. Que quelqu\'un ait survécu est une question sans témoin restant pour y répondre. Bienvenue, dans un cas comme dans l\'autre. Vous deux.',
  [roomChoiceTextKey('teleporter', 'refuse-stairs')]: 'Refusez. Cherchez des escaliers, une corniche, une corde — n\'importe quoi qui garde le fil intact.',
  [roomChoiceHintKey('teleporter', 'refuse-stairs')]: 'Il doit y avoir un autre moyen de traverser.',
  [roomChoiceOutcomeKey('teleporter', 'refuse-stairs', 0)]: 'Vous cherchez. Vous cherchez correctement — les murs, le sol-miroir, la trappe de service de la cabine. La pièce vous observe avec la patience de quelque chose qui a hébergé cette recherche exacte de nombreuses fois.',
  [roomChoiceOutcomeKey('teleporter', 'refuse-stairs', 1)]: 'Il n\'y a pas d\'escaliers. Il n\'y en a jamais eu. La pièce est honnête sur sa seule porte, et la porte est la cabine. Vous restez longtemps face au gouffre, puis — parce qu\'avancer est la seule direction que cet endroit vend — vous entrez quand même, n\'ayant rien gagné sauf la certitude d\'avoir épuisé les alternatives.',
  [roomChoiceOutcomeKey('teleporter', 'refuse-stairs', 2)]: 'Le Placeur : Pour ce que ça vaut — ceux qui cherchent arrivent de l\'autre côté identiques à ceux qui ont simplement fait confiance. Mais ils arrivent en ayant lutté pour cela, et certains voyageurs ont besoin exactement de ce reçu. Vous avez gardé le fil aussi longtemps que le fil a existé. Personne ne peut faire plus que cela. Si quelqu\'un peut même faire autant, c\'est la question pour laquelle cette pièce a été construite.',
  [roomChoiceTextKey('teleporter', 'copy-first')]: '« Exécutez-le en mode copie — imprimez celui de l\'autre côté SANS me désassembler. Ensuite, laissez-nous discuter tous les deux de qui traverse. »',
  [roomChoiceHintKey('teleporter', 'copy-first')]: 'Divisez la question avant d\'y répondre.',
  [roomChoiceOutcomeKey('teleporter', 'copy-first', 0)]: 'La cabine, prise au dépourvu, consulte son propre manuel. Le mode copie existe. Bien sûr qu\'il existe — la destruction n\'a jamais été techniquement nécessaire ; c\'était une courtoisie, pour garder les chiffres bien rangés.',
  [roomChoiceOutcomeKey('teleporter', 'copy-first', 1)]: 'Le vous lointain apparaît, vérifie ses mains avec votre geste exact, et regarde à travers le gouffre vers vous. Pendant un long moment vous êtes tous deux silencieux, car vous savez tous deux : quoi que vous ressentiez en ce moment — ce vertige d\'être l\'original — le vous lointain le ressent aussi, symétriquement, et se nomme lui-même l\'original. Il n\'y a aucune expérience que l\'un de vous pourrait mener pour trancher.',
  [roomChoiceOutcomeKey('teleporter', 'copy-first', 2)]: 'Le Placeur : Et voilà le scalpel, précisément. Si la copie est vous quand vous êtes détruit, pourquoi ne l\'est-elle pas quand vous ne l\'êtes pas ? Un philosophe a trouvé cette fourche il y a de très nombreuses années, et elle n\'a jamais cessé de saigner. (au vous lointain) Vous prendrez la cabine maintenant. (à vous) Et donc, avec le temps, vous aussi. Il n\'y a toujours pas de pont — seulement, maintenant, celui qui finira votre traversée pour vous. Soyez gentil avec lui. Il a eu une journée étrange aussi.',
  [roomExplanationKey('teleporter', 0)]: 'Une machine propose de vous faire traverser un gouffre impossible en vous scannant, vous détruisant, et vous réimprimant parfaitement de l\'autre côté — la copie se souviendra de tout et se sentira exactement comme si elle avait traversé. Mais « vous » êtes-vous mort ? C\'est l\'une des plus grandes énigmes de l\'identité personnelle : si chaque atome et chaque souvenir sont parfaitement préservés, importe-t-il que l\'original ait été détruit ? C\'est la version expérience de pensée d\'un fait réel — les cellules de votre corps meurent constamment et sont remplacées de toute façon, alors qu\'est-ce qui fait réellement de vous « vous » d\'un jour à l\'autre, sinon un fil physique ininterrompu ?',
  [roomNoteTitleKey('teleporter')]: 'L\'identité personnelle et le téléporteur',
  [roomNoteThinkersKey('teleporter')]: 'Derek Parfit · Raisons et personnes · John Locke',
  [roomNoteBodyKey('teleporter')]: 'Derek Parfit a construit le cas du téléporteur pour briser une hypothèse très ancienne : que l\'identité personnelle est un fait profond supplémentaire — un fil semblable à une âme qui survit ou non. Le scanner vous détruit et imprime une réplique parfaite ; la réplique se souvient d\'être entrée et se sent sans coupure. Êtes-vous mort ? La réponse scandaleuse de Parfit : la question est vide. Tout ce qui compte — continuité psychologique, mémoire, intention, caractère — est préservé ; la chose « supplémentaire » dont la survie vous inquiète n\'a jamais été là pour commencer. **L\'identité, argumentait-il, n\'est pas ce qui compte ; la continuité et la connexion le sont.** Son cas de la ligne de branchement (imprimer la copie sans détruire l\'original) expose la blessure : deux candidats, prétentions symétriques, aucun arbitre possible. Parfit rapportait qu\'intérioriser cela rendait la mort moins terrible — un changement de degré, pas la rupture d\'un fil métaphysique. Que cela vous console ou vous vide dépend généralement de quel côté de la cabine vous vous trouvez.',
});

// ---------- Act III: The Editor ----------
registerAll('v2', 'fr', {
  [roomBeatKey('editor', 0, 0)]: 'Un bureau, éclairé par une lampe, le genre de silence qui contient du mobilier. Sur le bureau : un unique dossier en papier kraft avec votre nom dessus — votre vrai nom, celui dont vous ne pouvez actuellement pas vous souvenir, que le dossier garde tactiquement retourné, face cachée.',
  [roomBeatKey('editor', 0, 1)]: 'À l\'intérieur du dossier se trouve votre pire souvenir. La pièce n\'a pas besoin de vous dire lequel. Votre corps vous l\'a déjà dit : d\'abord les épaules, puis l\'estomac, puis la météo du visage.',
  [roomBeatKey('editor', 0, 2)]: 'À côté du dossier, un stylo rouge. Les instructions sont gravées sur le stylo lui-même, en petit : UN TRAIT LE SUPPRIME. L\'ÉVÉNEMENT SE SERA TOUJOURS PRODUIT. VOUS N\'Y AUREZ SIMPLEMENT JAMAIS ÉTÉ.',
  [roomBeatKey('editor', 0, 3)]: 'Le Placeur : Pas de piège, cette fois. Le stylo fonctionne exactement comme décrit — pas de clause cachée, pas de piqûre ironique. Le seul coût est celui imprimé sur la boîte : vous, moins cela. Prenez tout le temps qu\'il vous faut. La lampe est patiente. Moi aussi, pour une fois.',
  [roomChoiceTextKey('editor', 'strike-it')]: 'Rayez-le. Personne n\'est obligé de porter cela.',
  [roomChoiceHintKey('editor', 'strike-it')]: 'L\'amputation propre.',
  [roomChoiceOutcomeKey('editor', 'strike-it', 0)]: 'Le stylo est léger. La ligne est courte. Le soulagement est immédiat, énorme et réel — cette pièce ne triche pas, et le poids se lève comme une main retirée de votre poitrine après des années.',
  [roomChoiceOutcomeKey('editor', 'strike-it', 1)]: 'Et puis, au fil des couloirs suivants, vous remarquez les bords du trou. Un certain genre de chagrin d\'étranger que vous reconnaissiez autrefois d\'un coup d\'œil — désormais simple météo sur un visage. Une patience que vous aviez, chèrement acquise quelque part, désormais sans financement. La blessure est partie. Ce qu\'elle soutenait aussi.',
  [roomChoiceOutcomeKey('editor', 'strike-it', 2)]: 'Le Placeur : Aucun jugement. Sincèrement. Certains poids sont porteurs, et certains sont simplement du poids, et même moi ne peux pas toujours dire lequel de l\'extérieur. Vous avez pris la décision depuis le seul siège qui avait vue sur elle.',
  [roomChoiceTextKey('editor', 'keep-it')]: 'Refermez le dossier. Gardez-le. Il est à vous.',
  [roomChoiceHintKey('editor', 'keep-it')]: 'Le navire tout entier, pourriture comprise.',
  [roomChoiceOutcomeKey('editor', 'keep-it', 0)]: 'Vous refermez le dossier et le faites glisser sur le bureau, et la pièce l\'accepte avec quelque chose comme du respect. Le poids se réinstalle là où il a toujours été. Il n\'est pas plus léger. Ce n\'était jamais l\'offre.',
  [roomChoiceOutcomeKey('editor', 'keep-it', 1)]: 'Mais quelque chose a changé, minutieusement : vous l\'avez maintenant choisi. Le souvenir était autrefois quelque chose qui vous arrivait. Depuis ce soir, c\'est quelque chose que vous portez délibérément — même pierre, prise différente.',
  [roomChoiceOutcomeKey('editor', 'keep-it', 2)]: 'Le Placeur : Pour le procès-verbal — c\'est la différence entre une cicatrice et une blessure. Même tissu. L\'une des deux a cessé d\'être écrite par quelqu\'un d\'autre.',
  [roomChoiceTextKey('editor', 'read-first')]: 'Ouvrez le dossier. Lisez-le — entièrement, correctement — avant de décider.',
  [roomChoiceHintKey('editor', 'read-first')]: 'Affrontez-le, puis choisissez.',
  [roomChoiceOutcomeKey('editor', 'read-first', 0)]: 'Vous ouvrez le dossier. Le lire est exactement aussi terrible que vous le craigniez et légèrement différent de ce dont vous vous souveniez — le souvenir, s\'avère-t-il, s\'était censuré lui-même pendant des années, limant le pire bord, en aiguisant un autre. Le document est la version intégrale. Vous lisez jusqu\'au bout. Vous ne saviez pas que vous en étiez capable.',
  [roomChoiceOutcomeKey('editor', 'read-first', 1)]: 'Et l\'ayant lu, le stylo paraît différent. Plus petit. Le souvenir est toujours terrible, mais il est maintenant terrible et attesté — par l\'unique témoin dont vous ne pourrez jamais perdre le témoignage. Vous le laissez dans le dossier, non rayé. Pas parce que ça ne fait pas mal. Parce que c\'est vrai, et que vous étiez là, et que quelqu\'un aurait dû l\'être.',
  [roomChoiceOutcomeKey('editor', 'read-first', 2)]: 'Le Placeur : (doucement) C\'est le choix le plus rare. La plupart des voyageurs choisissent entre porter et retrancher. Presque personne ne pense à enfin lire la chose. Le stylo est resté sur ce bureau très longtemps. La chaise dans laquelle vous venez de vous asseoir a toujours été le véritable instrument.',
  [roomExplanationKey('editor', 0)]: 'Un stylo peut effacer définitivement votre unique pire souvenir — sans effets secondaires, sans piège, il cesse simplement de vous être arrivé. L\'utiliseriez-vous ? Ceci demande si les souvenirs douloureux ne sont que de la souffrance dont vous seriez mieux sans, ou s\'ils ont silencieusement construit des parties de qui vous êtes — votre patience, votre empathie, votre compréhension de la douleur des autres. Pensez à une rupture difficile ou un grand échec qui a beaucoup fait mal sur le moment, mais dont vous pouvez maintenant voir qu\'il vous a appris quelque chose de réel sur vous-même. Effacer cette douleur effacerait-il aussi quelque chose que vous voudriez réellement garder ?',
  [roomNoteTitleKey('editor')]: 'La blessure et le grand livre',
  [roomNoteThinkersKey('editor')]: 'Nietzsche, amor fati · reconsolidation de la mémoire · Kierkegaard',
  [roomNoteBodyKey('editor')]: 'La formule de Nietzsche pour la grandeur était amor fati — aimer son destin, ne rien vouloir de différent, « non seulement supporter ce qui est nécessaire, encore moins le dissimuler… mais l\'aimer. » Non parce que la souffrance est bonne, mais parce que le moi qui juge la souffrance a été construit par elle : rayez le pire chapitre et le lecteur change aussi. La science moderne de la mémoire donne des dents à cette expérience de pensée — la recherche sur la reconsolidation montre que les souvenirs sont réécrits à chaque rappel, et des médicaments qui atténuent la charge émotionnelle d\'un souvenir existent déjà. La question n\'est plus de la science-fiction : si vous pouviez limer le chagrin, le devriez-vous ? L\'argument en faveur du stylo est réel ; personne n\'est moralement obligé de saigner pour le développement du caractère. L\'argument contre est plus discret : **la douleur s\'avère souvent porteuse — la source d\'une empathie spécifique, d\'une patience spécifique, d\'un refus spécifique de laisser autrui souffrir sans témoin.** Kierkegaard disait que la vie se vit en avant mais se comprend en arrière. Le dossier est la partie arrière. Éditeurs, faites attention avec ça. Note en marge : ce qui est effacé n\'est pas simplement disparu — c\'est dû.',
});

// ---------- Act III: The Introduction ----------
registerAll('v2', 'fr', {
  [roomBeatKey('introduction', 0, 0)]: 'La plus petite pièce de l\'établissement. Pas de mobilier, pas de sol-miroir, pas de machinerie — juste des proportions si exactes qu\'elles donnent l\'impression d\'être écoutées.',
  [roomBeatKey('introduction', 0, 1)]: 'La pièce parle. Sa voix est courtoise et sans localisation.',
  [roomBeatKey('introduction', 0, 2)]: 'LA PIÈCE : Bienvenue. Ce sera bref, ou ce sera la plus longue pièce de votre vie ; cette partie vous appartient. Une seule question. Qui êtes-vous ?',
  [roomBeatKey('introduction', 0, 3)]: 'Vous ouvrez la bouche — et remarquez, avec un léger vertige, combien de réponses sont déjà alignées, et comment chacune porte un badge.',
  [roomChoiceTextKey('introduction', 'give-name')]: 'Donnez votre nom — ou tendez la main vers lui, en tout cas.',
  [roomChoiceHintKey('introduction', 'give-name')]: 'Commencez par l\'étiquette.',
  [roomChoiceOutcomeKey('introduction', 'give-name', 0)]: 'LA PIÈCE : C\'est un nom. Un son que vos parents ont choisi avant de vous rencontrer, attaché par paperasse et répétition. Si vous le changiez demain, vous subsisteriez — ce qui signifie que ce n\'était jamais vous. C\'est une poignée. Je demandais la tasse.',
  [roomChoiceOutcomeKey('introduction', 'give-name', 1)]: 'La pièce dit cela sans cruauté, comme on rend un manteau qui n\'est pas le sien.',
  [roomChoiceTextKey('introduction', 'give-role')]: 'Répondez par ce que vous faites — votre travail, votre place, vos gens.',
  [roomChoiceHintKey('introduction', 'give-role')]: 'Vous êtes ce à quoi vous passez vos journées. Sûrement.',
  [roomChoiceOutcomeKey('introduction', 'give-role', 0)]: 'LA PIÈCE : Ce sont des rôles. Des positions dans les systèmes d\'autrui — employeur, famille, nation. Chacun existait avant que vous ne le remplissiez et sera repourvu après. Vous avez décrit les compartiments. Je demandais ce qui y est versé.',
  [roomChoiceOutcomeKey('introduction', 'give-role', 1)]: 'LA PIÈCE : (doucement) Les descriptions sont ce qui s\'est dissous, voyageur. C\'est pourquoi vous êtes ici. Qui les porte ?',
  [roomChoiceTextKey('introduction', 'give-story')]: 'Racontez-lui votre histoire — ce qui vous est arrivé, ce que vous avez survécu, ce que vous aimez.',
  [roomChoiceHintKey('introduction', 'give-story')]: 'Le moi narratif, en entier.',
  [roomChoiceOutcomeKey('introduction', 'give-story', 0)]: 'La pièce écoute tout cela. C\'est une bonne auditrice ; vous vous surprenez à lui raconter des choses que les couloirs n\'ont jamais demandées.',
  [roomChoiceOutcomeKey('introduction', 'give-story', 1)]: 'LA PIÈCE : C\'est une histoire. Belle, et vraie, et — remarquez — racontée au passé, par quelqu\'un se tenant en dehors d\'elle. L\'histoire requiert un narrateur. Le narrateur est ce que je demandais. Chaque phrase que vous venez de dire était la preuve que vous n\'êtes aucune phrase.',
  [roomExplanationKey('introduction', 0)]: 'Une pièce écarte chaque réponse possible à « qui êtes-vous ? » — votre nom, votre travail, même votre histoire de vie — une à une, et demande ce qui reste. Cela ressemble à un piège, mais c\'est une question philosophique réelle et ancienne : si vous retiriez chaque étiquette et chaque histoire sur vous-même, resterait-il un « vous » en dessous, ou « vous » êtes-vous entièrement fait de ces étiquettes et histoires ? Essayez vous-même un instant : si vous ne pouviez pas répondre avec votre nom, votre travail, votre rôle familial, ou une quelconque histoire de votre passé, que resterait-il même pour répondre ?',
  [roomBeatKey('introduction', 1, 0)]: 'LA PIÈCE : Nous avons maintenant retiré le nom, les rôles et l\'histoire. C\'est généralement le moment où les voyageurs deviennent soit en colère, soit très silencieux. Les deux sont un progrès.',
  [roomBeatKey('introduction', 1, 1)]: 'LA PIÈCE : Je demanderai une fois de plus, et je veux que vous remarquiez ce qui reste disponible pour répondre. Qui êtes-vous ?',
  [roomChoiceTextKey('introduction', 'insist')]: '« Non — JE SUIS mon histoire. Enlevez l\'histoire et il ne reste personne pour demander. »',
  [roomChoiceHintKey('introduction', 'insist')]: 'Défendez le moi narratif.',
  [roomChoiceOutcomeKey('introduction', 'insist', 0)]: 'LA PIÈCE : Une école défendable. Le moi comme sa propre biographie — pas de perle au centre, seulement le collier. Beaucoup de penseurs rigoureux ont vécu et sont morts dans cette position, et je ne prétendrai pas l\'avoir vaincue.',
  [roomChoiceOutcomeKey('introduction', 'insist', 1)]: 'LA PIÈCE : Mais permettez une observation en partant : à l\'instant, quand j\'ai menacé votre histoire, quelqu\'un a tressailli. Demandez, à votre loisir, qui c\'était. La porte est derrière vous. Elle n\'a jamais été verrouillée. Les portes ici le sont rarement ; ce sont les voyageurs qui s\'enferment eux-mêmes.',
  [roomChoiceTextKey('introduction', 'admit')]: '« Je ne sais pas. Rien de dicible ne reste. Qui que je sois est ce qui est encore là après tout cela — et cela n\'a pas de nom. »',
  [roomChoiceHintKey('introduction', 'admit')]: 'Dites l\'indicible.',
  [roomChoiceOutcomeKey('introduction', 'admit', 0)]: 'La pièce est silencieuse un long moment — non le silence de l\'absence, mais celui de quelque chose qui s\'incline.',
  [roomChoiceOutcomeKey('introduction', 'admit', 1)]: 'LA PIÈCE : Correct. Pas comme réponse — il n\'y a pas de réponse — mais comme honnêteté. Ce qui reste quand chaque description est retirée n\'est pas rien ; c\'est celui qui fait le retrait. Cela ne peut être trouvé en cherchant, car c\'est la recherche elle-même. Vous ne tiendrez pas cette pensée longtemps ; personne ne le fait ; ce n\'est pas un échec, c\'est la nature de la pensée.',
  [roomChoiceOutcomeKey('introduction', 'admit', 2)]: 'LA PIÈCE : Vous êtes entré dissous et effrayé par cela. Remarquez : ce qui s\'est dissous, c\'est l\'emballage. Allez-y doucement. Vous êtes le voyageur le moins perdu à être passé ici depuis un certain temps.',
  [roomChoiceTextKey('introduction', 'stay-silent')]: 'Ne dites rien du tout. Restez dans la question.',
  [roomChoiceHintKey('introduction', 'stay-silent')]: 'Laissez le silence répondre.',
  [roomChoiceOutcomeKey('introduction', 'stay-silent', 0)]: 'Vous restez dans la pièce sans répondre, et le non-répondre n\'est pas une esquive — la pièce peut faire la différence ; elle a entendu toutes les sortes de silence qui existent.',
  [roomChoiceOutcomeKey('introduction', 'stay-silent', 1)]: 'LA PIÈCE : (après un moment, chaleureusement) Oui. C\'est aussi une façon de le dire — peut-être la seule grammaire dans laquelle la réponse s\'insère. La question « qui êtes-vous » n\'a jamais manqué d\'information. C\'était une invitation à cesser de tendre la main vers les badges. Vous avez arrêté. Peu le font.',
  [roomChoiceOutcomeKey('introduction', 'stay-silent', 2)]: 'La porte s\'ouvre d\'elle-même, ce qui dans cet établissement est le plus grand compliment jamais enregistré.',
  [roomExplanationKey('introduction', 1)]: 'Ayant déjà abandonné votre nom, votre rôle et votre histoire, la pièce demande une fois de plus « qui êtes-vous ? » — et cette fois il ne reste presque rien d\'évident vers quoi tendre la main. C\'est la version la plus dure de la même question : la plupart des gens deviennent mal à l\'aise ou se taisent ici, car nous sommes tellement habitués à nous décrire avec des étiquettes que d\'être invité à répondre sans elles ressemble à se tenir dans une pièce vide, lumières éteintes. Il n\'y a pas de mauvaise réponse, mais remarquez le genre de réponse vers lequel vous tendez la main une fois toutes les faciles épuisées.',
  [roomNoteTitleKey('introduction')]: 'Le moi introuvable',
  [roomNoteThinkersKey('introduction')]: 'Hume · anattā (non-soi bouddhiste) · tradition apophatique',
  [roomNoteBodyKey('introduction')]: 'David Hume est parti à la recherche de son moi et a enregistré un célèbre résultat nul : chaque fois qu\'il s\'introspectait, il ne trouvait que des perceptions particulières — chaleur, froid, amour, colère — jamais le percevant lui-même. Sa conclusion : le moi est un faisceau d\'expériences, et le « propriétaire » est une habitude de grammaire. Vingt-deux siècles plus tôt, le Bouddha enseignait anattā : cherchez dans le corps, les sensations, les perceptions, les impulsions et la conscience, et aucun d\'eux ne se qualifie comme le moi permanent que nous supposons ; l\'hypothèse elle-même est la racine d\'une souffrance spécifique. La tradition apophatique — des neti neti des Upanishads (« pas ceci, pas ceci ») à Maître Eckhart — a transformé l\'échec en méthode : dépouillez chaque description, et ce qui reste n\'est pas rien mais le témoin innommable qui fait le dépouillement. Cette pièce n\'avait pas de solution car « qui êtes-vous ? » n\'est pas une question aux données manquantes. **Chaque réponse dicible est une description, et les descriptions se possèdent, ne s\'incarnent pas.** Vous réussissez toujours. La leçon est ce qui reste.',
});

// ---------- Act III: The Debt of the Dead ----------
registerAll('v2', 'fr', {
  [roomBeatKey('debt-of-dead', 0, 0)]: 'Un chevet. La pièce l\'a arrangé avec une spécificité terrible — l\'odeur d\'un hôpital essayant de sentir la lavande, une fenêtre avec le soir dedans, une chaise placée pour vous comme si vous aviez confirmé votre présence.',
  [roomBeatKey('debt-of-dead', 0, 1)]: 'Dans le lit se trouve celui qui vous a fait du tort. La pièce a laissé le visage légèrement flou, car ce n\'est pas une seule personne — c\'est quiconque votre poitrine vient de nommer. Le tort était réel. Cet endroit ne traite pas de malentendus ; ce qu\'ils ont fait, ils l\'ont fait, et cela a façonné le plan de votre vie.',
  [roomBeatKey('debt-of-dead', 0, 2)]: 'Ils sont en train de mourir. Réellement, imminemment — les machines sont passées de l\'urgence à la courtoisie. Et ils sont éveillés, et ils vous connaissent, et ils demandent, d\'une voix où il ne reste presque plus rien : « Peux-tu me pardonner ? »',
  [roomBeatKey('debt-of-dead', 0, 3)]: 'Ils le pensent vraiment. C\'est l\'unique cruauté de la pièce : vous pouvez voir qu\'ils le pensent, et que le penser vraiment ne change rien à ce qui a été fait. Les deux faits, pleinement éclairés, au même chevet.',
  [roomChoiceTextKey('debt-of-dead', 'forgive')]: '« Oui. Je te pardonne. » Dites-le, et pensez-le autant que vous le pouvez.',
  [roomChoiceHintKey('debt-of-dead', 'forgive')]: 'Libérez la dette — pour qui que ce soit qu\'elle libère.',
  [roomChoiceOutcomeKey('debt-of-dead', 'forgive', 0)]: 'Vous le dites. Les mots coûtent plus que vous ne le pensiez et pèsent moins une fois dehors — comme si vous aviez tenu une pierre contre un courant et enfin ouvert la main, et découvert que le courant vous tenait aussi.',
  [roomChoiceOutcomeKey('debt-of-dead', 'forgive', 1)]: 'Leur visage fait ce que font les visages quand le dernier compte d\'une vie se solde inopinément. Ils ne disent pas merci. Ils disent votre nom — correctement, doucement — et quelque chose dans le grand livre entre vous, qui n\'allait jamais s\'équilibrer, se ferme simplement à la place.',
  [roomChoiceOutcomeKey('debt-of-dead', 'forgive', 2)]: 'Pardonner n\'a pas rendu ce qu\'ils ont fait acceptable. Cela l\'a rendu terminé. Vous passerez des années à apprendre que ce sont des mots différents, et ce soir fut la première leçon.',
  [roomChoiceTextKey('debt-of-dead', 'refuse')]: '« Non. Je suis là — c\'est ce que j\'ai. Le pardon, ce n\'est pas ça. »',
  [roomChoiceHintKey('debt-of-dead', 'refuse')]: 'L\'honnêteté plutôt que l\'absolution.',
  [roomChoiceOutcomeKey('debt-of-dead', 'refuse', 0)]: 'Vous dites non. Vous le dites sans méchanceté — c\'est la partie qui coûte — et vous restez sur la chaise, ce qui dit ce que le non ne peut pas : qu\'ils comptaient assez pour que la blessure soit réelle, et que la blessure est assez réelle pour que son propriétaire ne la solde pas par convenance d\'un lit de mort.',
  [roomChoiceOutcomeKey('debt-of-dead', 'refuse', 1)]: 'Ils l\'accueillent. Quelque part sous la courtoisie des machines, vous voyez quelque chose de presque comme du respect : ils ont posé une question honnête à la fin de leur vie et ont reçu une réponse honnête, ce qui est plus que ce dont la plupart des fins sont pourvues.',
  [roomChoiceOutcomeKey('debt-of-dead', 'refuse', 2)]: 'Vous avez tenu la ligne, et êtes resté quand même. Certaines dettes sont enregistrées honnêtement plutôt que réglées faussement, et le registre, lui aussi, est une sorte d\'hommage — la preuve que ce qui est arrivé est arrivé, à quelqu\'un qui était vraiment là.',
  [roomChoiceTextKey('debt-of-dead', 'forgive-silently')]: 'Pardonnez-leur — dans votre poitrine, pleinement — et dites seulement : « Repose-toi maintenant. »',
  [roomChoiceHintKey('debt-of-dead', 'forgive-silently')]: 'Libérez la dette sans leur remettre le reçu.',
  [roomChoiceOutcomeKey('debt-of-dead', 'forgive-silently', 0)]: 'Intérieurement, vous ouvrez la main. La pierre part. Vous la sentez partir — c\'est réel, la libération, aussi réelle que n\'importe quelle version prononcée.',
  [roomChoiceOutcomeKey('debt-of-dead', 'forgive-silently', 1)]: 'À voix haute, vous dites seulement : « Repose-toi maintenant », et leurs yeux fouillent votre visage pour le verdict, et trouvent de la gentillesse là où le verdict devrait être, ce qu\'ils passeront leurs dernières heures à lire dans les deux sens.',
  [roomChoiceOutcomeKey('debt-of-dead', 'forgive-silently', 2)]: 'Vous avez gardé le pardon et retenu l\'absolution — vous êtes libéré sans déverrouiller leur porte. Remarquez, sans jugement, que c\'était l\'unique option où la miséricorde est restée entièrement de votre côté du lit. Peut-être était-ce sagesse. Peut-être était-ce le dernier petit versement de la dette, payé finalement dans leur monnaie.',
  [roomChoiceTextKey('debt-of-dead', 'ask-question')]: '« D\'abord — pourquoi ? Dis-moi la vérité. Ensuite je répondrai. »',
  [roomChoiceHintKey('debt-of-dead', 'ask-question')]: 'La question que vous n\'avez jamais pu poser.',
  [roomChoiceOutcomeKey('debt-of-dead', 'ask-question', 0)]: 'Vous posez la question qui s\'est tenue dans chaque embrasure de votre vie, et le mourant, qui n\'a plus aucune utilité pour ses défenses, y répond.',
  [roomChoiceOutcomeKey('debt-of-dead', 'ask-question', 1)]: 'La réponse est plus petite que la blessure. Elle l\'est toujours. Pas de malveillance sur un trône — une personne effrayée, un moment de faiblesse métastasé, des raisons qui embarrasseraient un écolier. Vous attendiez une architecture de cruauté et avez reçu un haussement d\'épaules qui a brisé votre vie. La déception est son propre remède étrange : rien d\'aussi petit ne mérite le trône qu\'il a occupé en vous.',
  [roomChoiceOutcomeKey('debt-of-dead', 'ask-question', 2)]: 'Ce que vous dites après — oui, ou non, ou repose-toi maintenant — compte moins que vous ne le pensiez. La question était la visite. Ils y répondent, et vous savez tous deux que le compte a enfin été vérifié, par les deux seules personnes qui l\'ont jamais tenu.',
  [roomExplanationKey('debt-of-dead', 0)]: 'Quelqu\'un qui vous a réellement fait du tort dans le passé est maintenant en train de mourir et demande sincèrement : « peux-tu me pardonner ? » — et vous pouvez voir qu\'il le pense vraiment, ce qui n\'efface pas ce qu\'il a fait. Il s\'agit de savoir si le pardon est quelque chose que vous devez à quelqu\'un simplement parce qu\'il est désolé et mourant, ou si l\'honnêteté sur le fait d\'avoir été blessé compte davantage que de lui offrir une fin paisible. Imaginez un ami qui a gravement trahi votre confiance il y a des années, s\'excusant maintenant sur son lit de mort — dites-vous ce qui le réconfortera, ce qui est honnêtement vrai pour vous, ou quelque chose entre les deux ? Il n\'y a pas de mauvais sentiment ici, seulement différentes sortes d\'honnêteté.',
  [roomNoteTitleKey('debt-of-dead')]: 'Le pardon et le grand livre',
  [roomNoteThinkersKey('debt-of-dead')]: 'l\'évêque Butler · Hannah Arendt · Jacques Derrida',
  [roomNoteBodyKey('debt-of-dead')]: 'L\'évêque Butler a défini le pardon comme le renoncement au ressentiment — ni excuser, ni oublier, ni réconcilier, mais refuser de continuer à payer des intérêts sur la blessure. Hannah Arendt appelait le pardon la seule véritable échappatoire à l\'irréversibilité du passé : sans lui, nous restons pour toujours la victime d\'un acte, et l\'auteur du tort pour toujours son auteur ; le pardon libère les deux parties d\'un cadre figé. Mais Derrida a vu le paradoxe au chevet : un pardon digne de ce nom pardonne l\'impardonnable — tout le reste n\'est que comptabilité, l\'annulation de dettes déjà abordables. Et le lit de mort aiguise chaque bord : des excuses sincères changent l\'auteur du tort, pas le tort ; votre pardon est demandé exactement au moment où le refuser devient cruel et l\'accorder peut sembler forcé. Il n\'y avait pas de bonne réponse sur cette chaise. Pardonner, refuser honnêtement, libérer silencieusement, et poser la question jamais posée sont quatre actes différents de prendre la blessure au sérieux — **ce qui était, peut-être, la seule dette qui était vraiment la vôtre à payer.**',
});

// ---------- Act III: Mary's Room ----------
registerAll('v2', 'fr', {
  [roomBeatKey('marys-room', 0, 0)]: 'Une cellule entièrement construite en niveaux de gris — murs, sol, la chaise unique, même l\'eau dans le verre sur le bureau, rendus dans des nuances entre blanc et noir. C\'est la seule pièce de l\'aile construite ainsi délibérément.',
  [roomBeatKey('marys-room', 0, 1)]: 'Sur le bureau : les papiers de toute une vie, reliés et référencés entre eux — chaque longueur d\'onde, chaque réponse rétinienne, chaque voie neuronale qui s\'active quand un être humain regarde la couleur rouge. Vous les avez lus. Vous pourriez réciter de mémoire la physique d\'un coucher de soleil, dans le noir, à l\'envers.',
  [roomBeatKey('marys-room', 0, 2)]: 'Vous n\'avez jamais vu de rouge. Pas une seule fois, pas par accident, pas par une fissure dans un rideau. La pièce a été construite autour de cette absence de la façon dont un trou de serrure est construit autour de l\'unique clé qui lui manque.',
  [roomBeatKey('marys-room', 0, 3)]: 'Dans le coin : un tiroir, scellé, étiqueté d\'une écriture que vous ne reconnaissez comme celle de personne mais en laquelle vous avez pourtant confiance. LE RESTE DE CELA.',
  [roomBeatKey('marys-room', 0, 4)]: 'Le Placeur : Tout dans ces papiers est vrai et complet, selon toute mesure que la physique est disposée à offrir. Je veux être honnête là-dessus avant que vous ne décidiez de quoi que ce soit. Rien dans le tiroir ne corrigera les papiers. Cela ne fera qu\'ajouter à eux — du moins c\'est la théorie.',
  [roomChoiceTextKey('marys-room', 'open-drawer')]: 'Ouvrez le tiroir.',
  [roomChoiceHintKey('marys-room', 'open-drawer')]: 'Laissez advenir un fait de plus, si c\'est tout ce que cela s\'avère être.',
  [roomChoiceOutcomeKey('marys-room', 'open-drawer', 0)]: 'Vous ouvrez le tiroir. À l\'intérieur : de la lumière, arrangée exactement à la longueur d\'onde que les papiers promettaient, reposant dans un plat peu profond comme quelque chose retenu à mi-souffle.',
  [roomChoiceOutcomeKey('marys-room', 'open-drawer', 1)]: 'Rouge.',
  [roomChoiceTextKey('marys-room', 'leave-sealed')]: 'Laissez-le scellé. Les faits suffisent déjà — c\'est la complétude avec une boîte non ouverte.',
  [roomChoiceHintKey('marys-room', 'leave-sealed')]: 'Le compte-rendu physique était censé suffire.',
  [roomChoiceOutcomeKey('marys-room', 'leave-sealed', 0)]: 'Vous refermez le tiroir sans l\'ouvrir, et faites glisser les papiers dans leur dossier, satisfait qu\'une description physique complète n\'ait aucune lacune méritant ce genre de cérémonie.',
  [roomChoiceOutcomeKey('marys-room', 'leave-sealed', 1)]: 'Le tiroir semble bourdonner très faiblement pour le reste de votre temps dans cette pièce — le bourdonnement particulier d\'une lettre non lue, posée exactement où vous l\'avez laissée, patiente d\'une manière que les lettres non lues ne le sont généralement pas.',
  [roomChoiceTextKey('marys-room', 'give-away')]: 'Prenez le tiroir, non ouvert, et portez-le à quelqu\'un qui n\'a jamais lu les papiers non plus.',
  [roomChoiceHintKey('marys-room', 'give-away')]: 'Laissez le voir appartenir à quelqu\'un d\'autre, pour une fois.',
  [roomChoiceOutcomeKey('marys-room', 'give-away', 0)]: 'Vous soulevez le tiroir — léger, et étonnamment chaud — et le portez dehors, passé les papiers, passé les murs gris, sans jamais soulever le couvercle.',
  [roomChoiceOutcomeKey('marys-room', 'give-away', 1)]: 'Le Placeur : Une gentillesse inhabituelle. La plupart des voyageurs qui atteignent cette pièce veulent le voir pour eux-mêmes — c\'est compréhensible ; c\'est la seule expérience que cette aile ne peut vous offrir deux fois. Vous donnez quelque chose que vous n\'avez pas encore. Je ne sais pas comment appeler cela, sinon généreux.',
  [roomExplanationKey('marys-room', 0)]: 'Une femme qui a passé toute sa vie dans une pièce en noir et blanc connaît chaque fait scientifique sur la couleur rouge — la longueur d\'onde exacte, comment les yeux et le cerveau la traitent — mais ne l\'a jamais réellement vue. Si elle voit enfin le rouge pour la première fois, apprend-elle quelque chose de nouveau, même si elle savait déjà « tout » à ce sujet ? Ceci demande si expérimenter quelque chose (comme goûter votre plat préféré, ou tomber amoureux) est un genre de savoir totalement différent de simplement connaître les faits à ce sujet. Vous pourriez lire chaque article scientifique sur le goût du chocolat et manquer encore quelque chose que vous n\'obtiendriez qu\'en le goûtant réellement.',
  [roomNoteTitleKey('marys-room')]: 'Ce que Mary ne savait pas',
  [roomNoteThinkersKey('marys-room')]: 'Frank Jackson · Thomas Nagel, l\'argument de la connaissance',
  [roomNoteBodyKey('marys-room')]: 'Frank Jackson a conçu Mary pour briser directement la confiance du physicalisme : élevée dans une pièce en noir et blanc, elle apprend chaque fait physique sur la vision des couleurs — longueurs d\'onde, cellules coniques, courbes de réponse du cortex visuel — sans jamais voir une couleur. Libérez-la, montrez-lui une tomate mûre, et quelque chose se produit qu\'aucun manuel ne l\'avait préparée à affronter. La question de Jackson : a-t-elle appris quelque chose de nouveau ? Si une description physique complète omet **à quoi ressemble le rouge**, la liste complète du physicalisme n\'a jamais été complète — certains faits, soutient l\'argument, sont des faits sur l\'expérience, et aucune description à la troisième personne ne les livre, aussi exhaustive soit-elle. Thomas Nagel avait déjà aiguisé une version compagne : vous pouvez tout savoir sur l\'écholocation d\'une chauve-souris et ne toujours pas savoir ce que ça fait d\'être une chauve-souris. Les physicalistes ont des réponses — Mary gagne une capacité, pas un fait ; une nouvelle façon de représenter un ancien fait, pas une nouvelle information. Aucune ne dégonfle entièrement l\'intuition présente avec vous dans cette pièce en ce moment. Le tiroir n\'allait jamais être expliqué par ce qui précédait. Il allait être rencontré.',
});

// ---------- Act III: The Butterfly's Dream ----------
registerAll('v2', 'fr', {
  [roomBeatKey('butterfly-dream', 0, 0)]: 'Une petite pièce tapissée du sol au plafond de panneaux de papier de riz, doucement éclairée de derrière comme si les murs eux-mêmes étaient la lampe. Un lit bas, défait, encore chaud.',
  [roomBeatKey('butterfly-dream', 0, 1)]: 'S\'allonger n\'était apparemment jamais optionnel. Vous y êtes déjà allongé, en plein réveil, comme on émerge d\'une sieste qu\'on ne voulait pas faire — incertain, pendant une longue seconde, quelle pièce est la vraie et laquelle vous quittez.',
  [roomBeatKey('butterfly-dream', 0, 3)]: 'Vous étiez, dans le rêve — vous en êtes presque sûr — un papillon. Pas symboliquement. Des ailes, un poids, la logique spécifique et insouciante de suivre tout ce qui sentait bon. Vous n\'avez pas, en tant que papillon, rêvé d\'être cela. Vous étiez simplement, entièrement, un papillon, de la même façon que vous êtes maintenant, entièrement, quiconque est allongé sur ce lit.',
  [roomBeatKey('butterfly-dream', 0, 4)]: 'Le Placeur : Zhuangzi a raconté cette histoire sur lui-même, bien avant que cet établissement n\'existe — il rêva qu\'il était un papillon, se réveilla incertain d\'être un homme qui avait rêvé être un papillon, ou d\'être maintenant un papillon rêvant qu\'il est un homme. Il ne l\'a jamais résolu. Je tiens à préciser que cette pièce n\'a pas l\'intention de réussir là où il a refusé de le faire.',
  [roomChoiceTextKey('butterfly-dream', 'wake-as-self')]: 'Insistez sur la version éveillée. C\'est vous qui décidez cela, maintenant, ce qui tranche la question.',
  [roomChoiceHintKey('butterfly-dream', 'wake-as-self')]: 'Brisez l\'égalité par décret.',
  [roomChoiceOutcomeKey('butterfly-dream', 'wake-as-self', 0)]: 'Vous vous asseyez, plantez vos pieds sur le sol, et déclarez — à la pièce, aux ailes qui s\'estompent, à quiconque de vous deux fait la déclaration — que ceci est l\'état vrai et que l\'autre était le rêve.',
  [roomChoiceOutcomeKey('butterfly-dream', 'wake-as-self', 1)]: 'La pièce accepte le jugement comme un juge accepte un plaidoyer qu\'il n\'a aucun motif d\'annuler : sans accord, et sans autre argument. Quelque part, brièvement, quelque chose avec des ailes avait cru exactement la même chose de lui-même, tout aussi sûrement.',
  [roomChoiceTextKey('butterfly-dream', 'stay-butterfly')]: 'Laissez cela en l\'état. Peu importe lequel des deux rêve, ce n\'est pas manifestement votre travail de le corriger.',
  [roomChoiceHintKey('butterfly-dream', 'stay-butterfly')]: 'N\'arbitrez pas une égalité dont vous ne voyez pas tout le plateau.',
  [roomChoiceOutcomeKey('butterfly-dream', 'stay-butterfly', 0)]: 'Vous vous rallongez et laissez la question garder ses deux réponses, comme vous laisseriez deux couleurs non mélangées sur la même toile parce que les séparer n\'était jamais vraiment nécessaire pour regarder le tableau.',
  [roomChoiceOutcomeKey('butterfly-dream', 'stay-butterfly', 1)]: 'Quelque chose dans votre poitrine qui insiste habituellement pour savoir lequel de vous deux est réel devient, pour un moment, agréablement silencieux. Les murs tapissés brillent de la même façon dans les deux cas.',
  [roomChoiceTextKey('butterfly-dream', 'refuse-distinction')]: 'Rejetez la prémisse. Il n\'y a pas de fait sur qui rêve — seulement deux expériences, chacune complète.',
  [roomChoiceHintKey('butterfly-dream', 'refuse-distinction')]: 'La réponse la plus coûteuse : pas de consolation, pas de verdict, pas de lit où se réveiller.',
  [roomChoiceOutcomeKey('butterfly-dream', 'refuse-distinction', 0)]: 'Vous le dites clairement : il n\'y a pas d\'homme qui a rêvé d\'un papillon, ni de papillon rêvant d\'un homme — seulement une transformation, un état devenant un autre, sans poste fixe se tenant en dehors des deux pour certifier lequel était l\'original.',
  [roomChoiceOutcomeKey('butterfly-dream', 'refuse-distinction', 1)]: 'C\'est la réponse correcte, si c\'en est une, et elle n\'apporte rien à quoi se raccrocher — pas de triomphe du réveil, pas d\'aisance de papillon, juste les murs tapissés brillant exactement de la chaleur qu\'ils ont toujours eue, indifférents à celui de vous deux qui demande.',
  [roomChoiceTextKey('butterfly-dream', 'compare-dreams')]: 'Tenez le formulaire de décharge de la machine à expériences à côté de ce rêve. L\'un des deux, au moins, vous l\'avez signé.',
  [roomChoiceHintKey('butterfly-dream', 'compare-dreams')]: 'Comparez le rêve artificiel que vous avez payé à celui-ci, non facturé.',
  [roomChoiceOutcomeKey('butterfly-dream', 'compare-dreams', 0)]: 'Vous posez le formulaire signé à plat contre le mur tapissé, côte à côte avec ce que cela est — éveil, rêve, papillon, moi.',
  [roomChoiceOutcomeKey('butterfly-dream', 'compare-dreams', 1)]: 'Le formulaire a une date, une ligne de signature, une clause sur les remboursements. Cette pièce n\'a rien de tout cela. Un seul de vos deux rêves, remarquez-vous, s\'est jamais soucié de demander la permission.',
  [roomExplanationKey('butterfly-dream', 0)]: 'Vous vous réveillez d\'un rêve où vous étiez un papillon, complètement convaincu dans le rêve que vous étiez vraiment un papillon — et maintenant vous ne pouvez pas être sûr à 100 % lequel est le rêve : êtes-vous une personne qui a rêvé d\'être un papillon, ou un papillon en ce moment rêvant qu\'il est une personne ? Ce n\'est pas censé être résolu — c\'est une vieille histoire célèbre (du philosophe Zhuangzi) utilisée pour titiller doucement à quel point nous sommes vraiment sûrs que « maintenant » est le réel, le solide. Vous êtes-vous déjà réveillé d\'un rêve si vif qu\'il vous a fallu quelques secondes pour vous souvenir de quelle vie était la vraie ?',
  [roomNoteTitleKey('butterfly-dream')]: 'La question du papillon',
  [roomNoteThinkersKey('butterfly-dream')]: 'Zhuangzi, le rêve du papillon',
  [roomNoteBodyKey('butterfly-dream')]: 'Zhuangzi, le philosophe taoïste, décrit avoir rêvé qu\'il était un papillon — voletant et content, inconscient de tout Zhuangzi — et s\'être réveillé en sursaut, incapable de décider s\'il était un homme qui venait de rêver être un papillon, ou s\'il est maintenant un papillon rêvant qu\'il est un homme. Il appelle cela la transformation des choses, et refuse, pointedly, de la résoudre : la question suppose un observateur fixe se tenant en dehors des deux états, vérifiant lequel est réel, et aucun observateur de ce genre n\'est disponible. Chaque expérience, tant qu\'elle dure, est totale et incontestée de l\'intérieur — le papillon ne soupçonne pas Zhuangzi, et Zhuangzi, en plein rêve, ne soupçonnait pas non plus le papillon. L\'épistémologie occidentale tend à vouloir un verdict : lequel est la réalité de base, lequel le rêve. La réponse de Zhuangzi est plus proche d\'un haussement d\'épaules élevé au rang de doctrine — l\'identité est provisoire, les états se transforment les uns en les autres, et chercher l\'unique véritable dormeur éveillé sous tout cela pourrait être la seule vraie erreur possible. **Les ailes n\'étaient la métaphore de rien. Elles étaient, entièrement, elles-mêmes, exactement aussi longtemps qu\'elles ont duré.**',
});

// ---------- Act III: Swampman ----------
registerAll('v2', 'fr', {
  [roomBeatKey('swampman', 0, 0)]: 'L\'orage dehors a mis la moitié des lumières de l\'aile en scintillement, et dans la pénombre stroboscopique, l\'unique chaise de la pièce est occupée. Par vous.',
  [roomBeatKey('swampman', 0, 1)]: 'Pas une copie au sens propre et mécanique du téléporteur — celle-ci est arrivée par accident, comme arrive un coup de foudre : un marais, un corps, un éclair, et après, se relevant de la boue, identique molécule pour molécule à vous, jusqu\'au manteau que vous portez justement.',
  [roomBeatKey('swampman', 0, 2)]: 'Il ne vous a jamais rencontré. Il n\'a également jamais rencontré personne — il s\'est formé il y a quarante secondes dans un marais qui n\'est pas dans ce bâtiment, avec vos souvenirs intacts et fonctionnels, votre écriture prête dans sa main, le visage de votre mère vivant dans un esprit qui existe depuis moins de temps qu\'il n\'en faut pour lire cette phrase.',
  [roomBeatKey('swampman', 0, 3)]: 'Il lève les yeux, un peu penaud de toute cette affaire, et dit, avec votre voix exacte : « Je sais de quoi ça a l\'air. Je ressentirais la même chose, à votre place. Je crois même que je le ressens, en fait — la même chose. C\'est bien là le problème, non ? »',
  [roomBeatKey('swampman', 0, 4)]: 'Le Placeur : Pas de piège dans la physique, cette fois non plus. Il a vos synapses, vos cicatrices, vos rancunes, jusqu\'à celle que vous nourrissez actuellement à son sujet. La seule chose qu\'il n\'a pas, c\'est un passé — aucune histoire ne le relie à la personne qui a grandi avec vos souvenirs. Si cela le disqualifie d\'être vous est, me dit-on, encore en débat. Pas par moi. Par des philosophes, surtout au dîner.',
  [roomChoiceTextKey('swampman', 'accept-them')]: '« Tu es moi. L\'histoire n\'a jamais été la partie porteuse — l\'esprit sur cette chaise fait tout ce que fait un moi. »',
  [roomChoiceHintKey('swampman', 'accept-them')]: 'L\'identité par le motif, pas par la lignée.',
  [roomChoiceOutcomeKey('swampman', 'accept-them', 0)]: 'Vous traversez la pièce et lui serrez la main, qui serre en retour avec votre propre légère hésitation, et quelque chose dans la lumière stroboscopique s\'installe, brièvement, en quelque chose de moins semblable à une scène de crime et de plus semblable à des retrouvailles familiales avec un préavis inhabituellement court.',
  [roomChoiceOutcomeKey('swampman', 'accept-them', 1)]: 'Le Placeur : Un jugement généreux, et cohérent — si ce qui compte est le motif plutôt que la provenance, le marais n\'est qu\'une méthode de livraison inhabituellement dramatique. Vous deux devrez régler, à votre propre rythme, à qui revient le tour d\'utiliser le nom.',
  [roomChoiceTextKey('swampman', 'deny-them')]: '« Aucun fil causal ne va de moi à toi. Tu es un étranger très convaincant. »',
  [roomChoiceHintKey('swampman', 'deny-them')]: 'L\'histoire n\'est pas optionnelle ; c\'est le tout qui est copié.',
  [roomChoiceOutcomeKey('swampman', 'deny-them', 0)]: 'Vous gardez vos distances, et il accepte cela avec une grimace que vous reconnaissez, car c\'est, après tout, votre propre grimace, déployée par quelqu\'un qui n\'avait littéralement jamais eu à l\'utiliser avant ce soir.',
  [roomChoiceOutcomeKey('swampman', 'deny-them', 1)]: 'Le Placeur : Cohérent aussi — si l\'identité requiert une chaîne causale ininterrompue vers la personne qui a vécu la vie dont on se souvient, celui-ci a des souvenirs mais pas de biographie, un journal sans la main de personne derrière l\'encre. Il continuera à croire qu\'il est vous quand même. La croyance, malheureusement, n\'a jamais requis de lignée valide.',
  [roomChoiceTextKey('swampman', 'split-the-coat')]: 'Offrez de diviser ce que vous avez — la pièce, le nom, ce qui vient ensuite — entre vous deux.',
  [roomChoiceHintKey('swampman', 'split-the-coat')]: 'Peut-être que la survie n\'a jamais été ce pour quoi il valait la peine de se disputer.',
  [roomChoiceOutcomeKey('swampman', 'split-the-coat', 0)]: 'Vous enlevez le manteau et le lui tendez, à moitié sérieusement, et pour un moment vous n\'êtes plus que deux personnes debout dans une mauvaise lumière, réglant la logistique plutôt que la métaphysique, ce qui s\'avère considérablement plus facile.',
  [roomChoiceOutcomeKey('swampman', 'split-the-coat', 1)]: 'Le Placeur : Derek Parfit aurait aimé cette pièce, je pense — il a passé une carrière à argumenter que la survie n\'a jamais été le prix pour lequel se battre ; ce qui compte, c\'est que quelqu\'un psychologiquement continu avec vous porte ce à quoi vous teniez vers l\'avant. Selon cette mesure, ce soir, vous avez tous les deux gagné. Essayez de ne pas laisser le manteau devenir un tout nouveau différend.',
  [roomChoiceTextKey('swampman', 'show-the-splinter')]: 'Sortez l\'éclat du bois original du navire et tenez-le en l\'air. « Des planches, encore. Dites-moi lequel de nous possède le voyage. »',
  [roomChoiceHintKey('swampman', 'show-the-splinter')]: 'La question du navire, portant un manteau.',
  [roomChoiceOutcomeKey('swampman', 'show-the-splinter', 0)]: 'Il regarde l\'éclat, puis vous, et rit — une fois, brièvement, un vrai rire, la première chose sans garde que l\'un de vous deux ait faite ce soir.',
  [roomChoiceOutcomeKey('swampman', 'show-the-splinter', 1)]: '« Je ne sais pas », dit-il, souriant toujours. « Mais je remarque qu\'aucun de nous ne l\'a jeté. » La question ne se résout pas. Elle devient, d\'une certaine manière, un peu plus petite quand même.',
  [roomExplanationKey('swampman', 0)]: 'La foudre frappe un marais et, par pur accident, assemble quelqu\'un identique molécule pour molécule à vous — mêmes souvenirs, même voix, même amour pour votre mère — sauf qu\'il n\'a été créé qu\'il y a quarante secondes et n\'a aucune histoire réelle d\'avoir vécu votre vie. Est-ce vous ? Ceci demande si ce qui fait de vous « vous » est votre esprit et vos souvenirs (auquel cas, oui, évidemment), ou si le fait d\'avoir réellement vécu la vie qui les a produits compte aussi (auquel cas, non — c\'est un étranger très convaincant). C\'est comme demander si un clone d\'IA parfait de votre personnalité, entraîné sur tout ce que vous avez jamais dit, serait vraiment vous, ou juste quelque chose portant votre voix.',
  [roomNoteTitleKey('swampman')]: 'L\'homme du marais',
  [roomNoteThinkersKey('swampman')]: 'Donald Davidson · Derek Parfit, histoire causale et ce qui compte',
  [roomNoteBodyKey('swampman')]: 'Donald Davidson a proposé Swampman comme réduction à l\'absurde : la foudre frappe un marais et, par accident cosmique, assemble un être identique molécule pour molécule à Davidson, souvenirs compris, sans aucune histoire causale le reliant à l\'original — pas d\'enfance, pas d\'apprentissage, pas de relation réelle avec les personnes dont il « se souvient ». La propre intuition de Davidson était que Swampman ne pouvait rien signifier par ses mots, puisque la signification requiert une histoire causale que la créature du marais n\'a jamais eue ; la représentation, selon cette vue, n\'est pas seulement structure, c\'est structure plus histoire. Derek Parfit, travaillant la même fourche sous un angle différent, a argumenté que l\'histoire n\'a jamais été le point : ce qui compte dans la survie est la continuité psychologique et la connexion — mémoire, intention, caractère portés vers l\'avant — pas un fil causal ininterrompu vers un morceau particulier de matière. Si Parfit a raison, le marais est un mécanisme de livraison étrange pour quelqu\'un qui est néanmoins vous, en tout sens qui vaille la peine d\'être voulu. Si Davidson a raison, la pièce est occupée par un étranger arrivé préchargé avec toute votre vie intérieure et rien de votre histoire. **Tous deux peuvent avoir raison sur ce qu\'ils mesurent chacun — ils n\'ont en fait jamais discuté de la même question.**',
});

// ---------- Act III: The Cave ----------
registerAll('v2', 'fr', {
  [roomBeatKey('the-cave', 0, 0)]: 'Une porte basse, facile à manquer, plus chaude que le couloir alentour. La lueur du feu passe sous l\'interstice comme dans les vieilles histoires — orange, instable, patiente.',
  [roomBeatKey('the-cave', 0, 1)]: 'À l\'intérieur : un feu, un mur, et un banc face au mur, comme si quelqu\'un avait construit cette pièce autour du seul but de s\'asseoir ici et de regarder.',
  [roomBeatKey('the-cave', 0, 5)]: 'Les formes sur le mur font exactement ce que vous avez fait. Pas de similaire. Exactement. Vous reconnaissez votre propre posture en silhouette avant de reconnaître le choix.',
  [roomBeatKey('the-cave', 0, 6)]: 'Le Placeur : Je n\'ai pas construit cette pièce, et je ne sais pas qui l\'a fait, bien que j\'aie une supposition que je garde pour moi. Elle n\'apparaît que pour les voyageurs qui sont déjà partis une fois et revenus. On me dit que ce détail compte. Je n\'ai jamais pu dire pourquoi.',
  [roomChoiceTextKey('the-cave', 'name-them')]: '« Je te reconnais. » Dites, à voix haute, à qui appartiennent ces choix.',
  [roomChoiceHintKey('the-cave', 'name-them')]: 'Nommez ce que vous observez — le genre de regard le plus difficile.',
  [roomChoiceOutcomeKey('the-cave', 'name-them', 0)]: 'Vous le dites. Pas le nom qu\'un étranger utiliserait — le petit nom vrai, celui que vous utilisiez sur vous-même dans le noir, celui que les ombres sur le mur reconnaîtraient si les ombres pouvaient écouter.',
  [roomChoiceOutcomeKey('the-cave', 'name-them', 1)]: 'Le Placeur : La plupart des voyageurs regardent. Presque aucun ne nomme ce qu\'il observe. Je ne sais pas exactement ce que cela coûte, mais je peux voir, d\'ici, que cela coûte quelque chose. Le mur s\'assombrit ensuite, comme un feu qui s\'apaise une fois qu\'on lui a donné précisément ce qu\'il voulait.',
  [roomChoiceTextKey('the-cave', 'watch-silent')]: 'Regardez sans parler. Laissez les ombres achever leur jeu.',
  [roomChoiceHintKey('the-cave', 'watch-silent')]: 'Témoigner sans narrer.',
  [roomChoiceOutcomeKey('the-cave', 'watch-silent', 0)]: 'Vous ne dites rien. Les ombres achèvent leurs petites performances exactes sans votre narration, sans votre correction, sans votre permission.',
  [roomChoiceOutcomeKey('the-cave', 'watch-silent', 1)]: 'C\'est plus facile ainsi, et vous remarquez la facilité, et vous vous remarquez la remarquant, et le feu ne semble se soucier d\'aucune des deux versions de vous.',
  [roomChoiceTextKey('the-cave', 'turn-to-fire')]: 'Détournez-vous du mur vers le feu lui-même — la lumière, pas les formes qu\'il projette.',
  [roomChoiceHintKey('the-cave', 'turn-to-fire')]: 'Regardez le projecteur, pas les ombres, et partez vers lui.',
  [roomChoiceOutcomeKey('the-cave', 'turn-to-fire', 0)]: 'Vous vous détournez du mur, délibérément, vers la flamme qui fait le vrai travail — le mur n\'a jamais été qu\'un écran, et les écrans, aussi bien éclairés soient-ils, n\'ont jamais été là où vivait la lumière.',
  [roomChoiceOutcomeKey('the-cave', 'turn-to-fire', 1)]: 'Le Placeur : Un choix inhabituel pour cette pièce en particulier. La plupart des voyageurs étudient les formes aussi longtemps que le feu le permet. Vous avez plutôt regardé la chose qui rend les formes possibles, et avez marché vers elle avant que le jeu ne soit terminé. Je n\'ai aucun verdict sur si c\'est de la sagesse ou simplement de l\'impatience. Une pièce aussi ancienne n\'a peut-être pas le droit d\'avoir une opinion.',
  [roomExplanationKey('the-cave', 0)]: 'On vous montre vos propres choix passés, joués comme des ombres sur un mur, et on vous demande de simplement regarder — ou de les nommer comme les vôtres. Cette pièce n\'apparaît qu\'une fois que vous avez déjà traversé ce voyage auparavant, et elle est construite sur la célèbre « Allégorie de la caverne » de Platon : des gens qui n\'ont jamais vu que des ombres sur un mur prennent les ombres pour la totalité de la réalité, et il est réellement inconfortable de reculer et de vraiment regarder ce qui les a projetées. Ceci est moins un dilemme qu\'une invitation à regarder honnêtement les schémas de vos propres choix sans détourner le regard.',
  [roomNoteTitleKey('the-cave')]: 'Le feu et le mur',
  [roomNoteThinkersKey('the-cave')]: 'Platon, l\'ascension hors de la caverne',
  [roomNoteBodyKey('the-cave')]: 'L\'allégorie de Platon, dans la République, imagine des prisonniers enchaînés depuis l\'enfance dans une caverne, face à un mur, regardant des ombres qu\'un feu derrière eux projette — des ombres qu\'ils prennent, comprensiblement, pour la totalité de la réalité, n\'ayant jamais eu de raison de soupçonner qu\'il y avait plus. Libéré et traîné à la lumière du soleil, le prisonnier est d\'abord aveuglé, puis furieux, puis lentement transformé — et la question plus dure de Platon suit immédiatement : que se passe-t-il si ce prisonnier redescend pour le dire aux autres ? Ils ne le remercieront pas. Platon suggère qu\'ils essaieront de le tuer, parce que les ombres fonctionnaient bien et que personne n\'aime qu\'on lui dise que tout son monde était un mur. Cette pièce fait quelque chose que l\'allégorie n\'a jamais tout à fait osé : elle vous tend vos propres ombres, projetées par votre propre feu, et vous demande de vous observer exactement sous l\'angle que les prisonniers n\'ont jamais eu. **Les chaînes n\'ont jamais été la partie intéressante. Le mur ne vous mentait jamais délibérément. Il n\'a simplement jamais mentionné qu\'il était un mur.**',
});

// ---------- Act III: The Free Will Waiting Room ----------
registerAll('v2', 'fr', {
  [roomBeatKey('free-will', 0, 0)]: 'Une salle d\'attente de nouveau — faisant écho à la première, mais celle-ci a une rangée de gros boutons amicaux le long du mur : bleu, rouge, vert, et un sans étiquette.',
  [roomBeatKey('free-will', 0, 1)]: 'Au-dessus des boutons, un écran. Sur l\'écran, un tableau de paris. Le Placeur se tient à côté, avec une visière de bookmaker et une expression de sérénité insupportable.',
  [roomBeatKey('free-will', 0, 2)]: 'Le Placeur : Un jeu simple. Appuyez sur n\'importe quel bouton que vous voulez, quand vous voulez, entièrement de votre propre libre arbitre. J\'ai déjà écrit à l\'avance lequel vous appuierez. Je n\'ai jamais perdu une seule fois. Je m\'en excuserais, mais vous alliez toujours m\'entendre le dire.',
  [roomBeatKey('free-will', 0, 3)]: 'Vous tendez la main — juste pour tester — et le bouton BLEU s\'allume, chaleureusement, une seconde entière avant que votre main ne s\'engage. Vous n\'aviez pas encore décidé. Vous auriez juré ne pas avoir encore décidé.',
  [roomBeatKey('free-will', 0, 4)]: 'Le Placeur : (lisant le tableau) « Bleu, d\'abord — pour tester. » Vous allez maintenant vous sentir brièvement rebelle, et considérer le rouge. Prenez votre temps avec ça. Le tableau l\'a déjà pris.',
  [roomBeatKey('free-will', 0, 5)]: 'Le Placeur : Simplement dit, si cela aide : tout ce que vous êtes sur le point de faire dans cette pièce a, apparemment, déjà été écrit. La seule question ouverte est de savoir si être prévisible et être libre ont jamais vraiment été opposés.',
  [roomChoiceTextKey('free-will', 'press-red')]: 'Appuyez sur ROUGE — précisément parce que le tableau dit que vous ne le ferez pas. Surpassez le tableau en rébellion.',
  [roomChoiceHintKey('free-will', 'press-red')]: 'Brisez la prédiction par la force.',
  [roomChoiceOutcomeKey('free-will', 'press-red', 0)]: 'Vous frappez le rouge. La cloche sonne. Le tableau, déplié d\'une ligne de plus, indique : « Rouge, avec défi, croyant que cela prouve quelque chose. »',
  [roomChoiceOutcomeKey('free-will', 'press-red', 1)]: 'Le Placeur : La rébellion était dans la prévision, voyageur — c\'est le temps le plus prévisible que vous ayez. Tout système déterminé semble faire tourner sa propre petite défiance ; c\'est ce qui lui permet de se sentir exceptionnel. Ne soyez pas gêné. Le bouton rouge est appuyé plus que tout autre dans cette pièce. Vous êtes en bonne compagnie.',
  [roomChoiceTextKey('free-will', 'dont-press')]: 'N\'appuyez sur rien. Croisez les bras. Refusez le jeu entier.',
  [roomChoiceHintKey('free-will', 'dont-press')]: 'On ne peut pas prédire ce qui n\'arrive jamais.',
  [roomChoiceOutcomeKey('free-will', 'dont-press', 0)]: 'Vous croisez les bras. Les minutes passent. La pièce est très douée avec les minutes.',
  [roomChoiceOutcomeKey('free-will', 'dont-press', 1)]: 'Le Placeur : (retournant le tableau ; il indiquait, depuis le début, « tentera de ne pas appuyer — durée estimée, quatre minutes ») L\'abstention est aussi un mouvement. Le tableau tient compte de tout l\'espace des options, y compris la fierté de se tenir en dehors. Quatre minutes, presque exactement. La plupart des voyageurs craquent à deux.',
  [roomChoiceTextKey('free-will', 'press-knowing')]: 'Appuyez sur BLEU — celui prédit — lentement, délibérément, exprès. « Cela allait toujours arriver, ET je le choisis. »',
  [roomChoiceHintKey('free-will', 'press-knowing')]: 'Cessez de lutter contre la prévision. Possédez le temps qu\'il fait.',
  [roomChoiceOutcomeKey('free-will', 'press-knowing', 0)]: 'Vous appuyez sur bleu — exactement le bouton nommé par le tableau — non par reddition mais avec la délibération d\'une signature. La cloche sonne. Cette fois, cela ressemble moins à marquer des points et davantage à un accord.',
  [roomChoiceOutcomeKey('free-will', 'press-knowing', 1)]: 'Le Placeur : Voilà. L\'issue n\'a jamais été de battre le tableau. C\'est de remarquer que « c\'était déterminé » et « je l\'ai choisi » peuvent être deux descriptions du même événement — la prévision et le temps qu\'il fait, se disputant sur lequel a fait pleuvoir. Votre choix fait partie de la machinerie. La machinerie fonctionne à travers le choix, pas autour de lui.',
  [roomChoiceOutcomeKey('free-will', 'press-knowing', 2)]: 'Le Placeur : J\'ai quand même gagné, techniquement. Mais vous êtes le premier aujourd\'hui à rendre la victoire secondaire, ce qui est la chose la plus proche d\'une défaite que je puisse avoir. La porte est ouverte. Elle allait toujours l\'être.',
  [roomChoiceTextKey('free-will', 'press-unlabeled')]: 'Appuyez sur celui sans étiquette. Quoi que ce soit, ce n\'est pas au menu.',
  [roomChoiceHintKey('free-will', 'press-unlabeled')]: 'Le bouton que personne n\'explique.',
  [roomChoiceOutcomeKey('free-will', 'press-unlabeled', 0)]: 'Vous appuyez sur le bouton sans étiquette. Quelque part au fond de l\'établissement, une bouilloire commence à bouillir.',
  [roomChoiceOutcomeKey('free-will', 'press-unlabeled', 1)]: 'Le Placeur : C\'est le bouton du thé. C\'est aussi écrit sur le tableau : « choisira le mystère plutôt que le sens ; prend du lait. » L\'option sans étiquette semble la plus libre, n\'est-ce pas. Remarquez, cependant, qu\'un menu avec « aucune de ces réponses » imprimé dessus est toujours un menu. Buvez. Vous l\'avez choisi, et il arrivait toujours, et c\'est un thé plutôt bon. Ces trois choses sont vraies à la fois. C\'est toute la leçon, et moins cher qu\'un séminaire.',
  [roomExplanationKey('free-will', 0)]: 'Une machine prétend avoir déjà écrit, à l\'avance, exactement quel bouton vous êtes sur le point d\'appuyer — et elle ne s\'est encore jamais trompée. Quoi que vous fassiez, même essayer de la contredire exprès, semble aussi avoir été prédit. C\'est la grande question derrière le « libre arbitre » : si tout en vous (votre cerveau, votre passé, vos habitudes) cause vos choix, vos choix sont-ils encore vraiment « libres », ou juste le résultat de choses que vous n\'avez pas choisies ? Pensez à quel point vous pourriez être prévisible pour quelqu\'un qui vous connaît vraiment bien — être prévisible signifie-t-il que vous ne choisissez pas réellement, ou les deux peuvent-ils être vrais en même temps ?',
  [roomNoteTitleKey('free-will')]: 'Le libre arbitre et la prévision',
  [roomNoteThinkersKey('free-will')]: 'Benjamin Libet · déterminisme · compatibilisme — Hume, Frankfurt, Dennett',
  [roomNoteBodyKey('free-will')]: 'Dans les années 1980, Benjamin Libet a découvert qu\'un potentiel de préparation apparaît dans le cerveau un laps de temps mesurable avant que les sujets ne rapportent avoir décidé de bouger — le bouton s\'allume, semble-t-il, avant que « vous » n\'appuyiez dessus. Les gros titres ont enterré le libre arbitre ; les petits caractères étaient plus subtils (Libet lui-même a noté une fenêtre de veto, et des travaux ultérieurs remettent en question ce que le potentiel de préparation mesure réellement). Mais la question plus profonde précède les électrodes : si chaque événement a des causes, vos choix inclus, en quel sens sont-ils les vôtres ? Le déterminisme dur dit : en aucun. Le libre arbitre libertaire dit que la chaîne causale se brise en vous — d\'une manière ou d\'une autre. Le compatibilisme, la philosophie de travail de la plupart des philosophes aujourd\'hui, dissout le combat : la liberté n\'a jamais requis d\'exemption de la causalité ; elle signifie agir depuis sa propre délibération, sans contrainte — la machinerie fonctionnant à travers votre choix plutôt qu\'autour de lui. **« Aurais-je pu faire autrement ? » compte peut-être moins que « était-ce moi qui l\'ai fait ? »** Vous alliez toujours lire cette note. Vous venez aussi de le choisir. Les deux phrases, une seule tasse.',
});
